import{showMedicine}from './medicine-visuals.js?v=20261023-physicscomplete01';import{medicineTasks,validMedicineAnswer,contactNetwork,selectedCohort,acceptableDose,doseData}from './medicine-models.js?v=20261023-physicscomplete01';export{showMedicine};
export function mountMedicine(l,p,root,{save,done,feedback}){let w=p.widget,tasks=medicineTasks[l.widget.slice(9)];w.medTask??=0;w.medDrafts??={};w.medPassed??=[];let index=w.medTask%tasks.length,t=tasks[index],v=w.medDrafts[index]??={state:0,answer:'',seen:[]},$=s=>root.querySelector(s);const select=(id,label,opts,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${opts.map(([a,b])=>`<option value="${a}" ${String(value)===String(a)?'selected':''}>${b}</option>`).join('')}</select>`,number=(id,label,value)=>`<label class="field-label" for="${id}">${label}</label><input class="lab-input" type="number" step="any" id="${id}" value="${value??''}">`,near=(x,a)=>x!==''&&x!==undefined&&Number.isFinite(Number(x))&&Math.abs(Number(x)-a)<.001;let body='',draw=()=>{},valid=()=>false,help='Use the evidence before recording.',record=()=>{};
if(t.type==='compare'){body=select('medState','Compare model state',t.states.map((s,i)=>[i,s[1]]),v.state)+select('medPrediction',t.prompt,t.choices.map((s,i)=>[i,s]),v.answer)+'<button class="secondary" id="revealMed">Reveal comparison →</button><p id="medReadout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.state;showMedicine(t.scene,{kind:t.scene,state:t.states[v.state][0],revealed:r,title:t.title,stateLabel:t.states[v.state][1],result:r?t.results[v.state]:''});$('#medReadout').textContent=r?t.results[v.state]:'Predict before revealing.';};record=()=>{if(v.revealed!==v.state||!validMedicineAnswer(t,v.state,v.answer)){feedback(t.why+' Predict and reveal this comparison first.',true);return false;}if(!v.seen.includes(v.state))v.seen.push(v.state);return true;};valid=()=>v.seen.length===t.states.length;help=t.why;}
else if(t.type==='network'){v.coverage??=0;v.steps??=0;body='<p>20 nodes, fixed contacts, one infected seed. Protected nodes cannot acquire/transmit this pathogen in this idealised model. No births, recovery or imperfect protection; not a real threshold.</p><label class="field-label" for="medCoverage">Protected proportion / %</label><input id="medCoverage" type="range" min="0" max="80" step="40" value="'+v.coverage+'"><p id="coverageLabel"></p>'+select('networkPrediction','Compared with no protection after5 steps…',[['same','Same spread in baseline'],['less','Fewer infected through blocked chains'],['all','Every susceptible person is guaranteed safe']],v.networkPrediction)+'<button class="secondary" id="stepNetwork">Advance one contact step →</button><p id="medReadout" aria-live="polite"></p>';draw=()=>{let n=contactNetwork(v.coverage,v.steps);showMedicine('network',{coverage:v.coverage,steps:v.steps,title:t.title,stateLabel:v.coverage+'% protected · step'+v.steps});$('#coverageLabel').textContent=v.coverage+'% · '+n.protectedNodes.length+' protected nodes';$('#medReadout').textContent='Step '+v.steps+'/5 · '+n.infected.length+' infected including seed · '+(20-n.infected.length-n.protectedNodes.length)+' susceptible and not yet infected.';};record=()=>{if(v.steps!==5||v.networkPrediction!==(v.coverage===0?'same':'less')){feedback('Predict the comparison, then advance all5 steps. Protected links interrupt chains; remaining susceptible people are not guaranteed safe.',true);return false;}if(!v.seen.includes(v.coverage))v.seen.push(v.coverage);return true;};valid=()=>[0,40,80].every(x=>v.seen.includes(x));help='Compare all three coverage settings. Network shape and perfect protection are assumptions; no universal coverage threshold follows.';}
else if(t.type==='selection'){v.pressure??='on';v.step??=0;body='<p>Start:18 susceptible(S),2 resistant(R). Existing variation precedes treatment. Steps are illustrative, not measured generations or a clinical course.</p>'+select('medPressure','Apply antibiotic selection?',[['on','Yes: susceptible killed'],['off','No antibiotic in comparison']],v.pressure)+select('selectionPrediction','Predict the final resistant proportion',[['higher','Higher than the initial proportion'],['same','Same as the initial proportion'],['need','Cells deliberately change because they need to']],v.selectionPrediction)+'<button class="secondary" id="stepSelection">Advance lineage step →</button><p id="medReadout" aria-live="polite"></p>'+number('beforePercentage','Initial resistant percentage / %',v.beforePercentage)+number('afterPercentage','Final resistant percentage / %',v.afterPercentage)+select('selectionReason','Mechanism',[['selection','Variants survive differently and reproduce'],['directed','Drug instructs each cell to mutate']],v.selectionReason);draw=()=>{let c=selectedCohort(v.pressure==='on',v.step);showMedicine('selection',{antibiotic:v.pressure==='on',step:v.step,title:t.title,stateLabel:['Existing variants','Survival comparison','Descendants'][v.step]});$('#medReadout').textContent='Step'+v.step+'/2 · S:'+c.susceptible+' · R:'+c.resistant+' · total:'+c.total;};record=()=>{let c=selectedCohort(v.pressure==='on',2);if(v.step!==2||v.selectionPrediction!==(v.pressure==='on'?'higher':'same')||!near(v.beforePercentage,10)||!near(v.afterPercentage,c.percent)||v.selectionReason!=='selection'){feedback('Start2/20. Compare survival then descendants, using R÷total×100. Variation existed before exposure; selection changes who leaves descendants.',true);return false;}if(!v.seen.includes(v.pressure))v.seen.push(v.pressure);return true;};valid=()=>['on','off'].every(x=>v.seen.includes(x));help='Compare both conditions. Total numbers and proportions are different measures; resistance belongs to bacteria, not the patient.';}
else if(t.type==='pipeline'){v.evidenceIndex??=0;let i=v.evidenceIndex%4,name=['Isolated laboratory cells','Laboratory tissue','Live-animal laboratory test','Healthy volunteers and patients'][i];body='<p>Classify evidence: <strong>'+name+'</strong>. Preclinical systems are examples, not a compulsory order within the laboratory stage.</p>'+select('evidenceClass','Testing stage',[['preclinical','Preclinical'],['clinical','Clinical']],v.evidenceClass)+'<button class="secondary" id="placeEvidence">Record evidence source →</button>'+select('humanStartingDose','When testing starts in people…',[['low','Very low dose; monitor carefully'],['max','Use maximum dose without monitoring']],v.humanStartingDose);draw=()=>showMedicine('preclinical:'+['cells','tissues','animals','clinical'][i],{title:t.title,stateLabel:name});record=()=>true;valid=()=>[0,1,2,3].every(x=>v.seen.includes(x))&&v.humanStartingDose==='low';help='Cells, tissues and live animals are preclinical. Healthy volunteers/patients are clinical; start very low and monitor.';}
else if(t.type==='design'){body=select('trialAllocation','Assign patient groups',[['random','Random allocation; comparable procedures'],['severity','All most-severe cases only in drug group']],v.trialAllocation)+select('trialPlacebo','Comparison preparation',[['inactive','Resembles treatment; lacks active drug'],['strong','Secretly stronger active drug']],v.trialPlacebo)+select('trialBlind','Who is unaware during outcome assessment?',[['both','Participants and outcome assessors'],['participant','Only participants'],['none','Everyone knows allocations']],v.trialBlind)+select('trialStart','Initial human testing',[['low','Healthy volunteers/patients; very low dose'],['skip','Skip safety and use largest dose']],v.trialStart)+'<button class="secondary" id="revealDesign">Inspect design →</button><p id="medReadout"></p>';draw=()=>{showMedicine('trial:blind',{title:t.title,stateLabel:v.designRevealed?'Inspect coded A/B groups':'Plan before comparing groups'});$('#medReadout').textContent=v.designRevealed?'Two coded groups use the same outcome measure. Random allocation, placebo and double blinding address different sources of bias.':'Design a fair comparison, then inspect it.';};valid=()=>v.designRevealed&&v.trialAllocation==='random'&&v.trialPlacebo==='inactive'&&v.trialBlind==='both'&&v.trialStart==='low';record=()=>true;help='Use cautious initial testing, random allocation and a placebo comparison. Double blind means participants AND outcome assessors are unaware during the comparison.';}
else if(t.type==='dose'){v.level??=0;body='<p>Original data; arbitrary dose levels. Classroom criterion: benefit≥60%, harm≤10%. Find the lowest tested level meeting both. These are not treatment doses.</p><label class="field-label" for="medDose">Inspect dose level</label><input id="medDose" type="range" min="0" max="3" step="1" value="'+v.level+'"><button class="secondary" id="inspectDose">Record observation →</button><p id="medReadout"></p>'+number('chosenDose','Chosen tested level',v.chosenDose)+select('doseReason','Why this level?',[['balance','Meets benefit and harm criteria'],['largest','Largest must always be best']],v.doseReason);draw=()=>{showMedicine('dose',{level:v.level,title:t.title,stateLabel:'Inspected level'+v.level});let d=doseData[v.level];$('#medReadout').textContent='Level'+d.level+' · benefit'+d.benefit+'% · harm'+d.harm+'%';};valid=()=>[0,1,2,3].every(x=>v.seen.includes(x))&&v.chosenDose!==''&&acceptableDose(v.chosenDose)&&v.doseReason==='balance';record=()=>true;help='Inspect all4 levels. Level1 misses benefit, level3 exceeds harm; select the lowest tested level satisfying both criteria.';}
else{body='<p>Original parallel groups:100 participants each.65 improved with drug;40 with placebo. Other trial quality and uncertainty still matter.</p>'+number('drugPercent','Drug improvement / %',v.drugPercent)+number('placeboPercent','Placebo improvement / %',v.placeboPercent)+number('differencePoints','Drug minus placebo / percentage points',v.differencePoints)+select('trialConclusion','Supported interpretation',[['compare','25-point group difference; not every improvement caused by drug'],['all','All65 improvements must be drug effects'],['zero','Placebo results must be erased']],v.trialConclusion);draw=()=>showMedicine('results',{title:t.title});valid=()=>near(v.drugPercent,65)&&near(v.placeboPercent,40)&&near(v.differencePoints,25)&&v.trialConclusion==='compare';record=()=>true;help='Convert each count out of100 to a percentage, then subtract. The40% placebo improvement shows why all65 drug-group improvements cannot simply be attributed to the drug.';}
root.innerHTML=`<p><b>${index+1} / ${tasks.length} · ${t.title}</b></p>${body}<p id="medEvidence"></p><div class="model-actions"><button class="secondary" id="recordMed">Record reasoning</button><button class="secondary" id="nextMed">Next challenge →</button></div><p id="medProgress">${w.medPassed.length} / ${tasks.length} complete</p>`;
const remount=()=>mountMedicine(l,p,root,{save,done,feedback}),click=(id,fn)=>{if($('#'+id))$('#'+id).onclick=fn;},readEvidence=()=>{$('#medEvidence').textContent=['design','results'].includes(t.type)?'':t.type==='compare'?'Recorded: '+t.states.map((s,i)=>(v.seen.includes(i)?'✓ ':'○ ')+s[1]).join(' · '):'Recorded comparisons: '+(v.seen.length?v.seen.join(', '):'none');};
for(let el of root.querySelectorAll('select,input'))el.onchange=e=>{let id=el.id,val=e.target.value;if(id==='medState'){v.state=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(id==='medPrediction')v.answer=val;else if(id==='medCoverage'){v.coverage=Number(val);v.steps=0;v.networkPrediction='';save();remount();return;}else if(id==='medPressure'){v.pressure=val||'on';v.step=0;v.selectionPrediction='';v.afterPercentage='';save();remount();return;}else if(id==='medDose')v.level=Number(val);else v[id]=val;save();draw();};
for(let id of['beforePercentage','afterPercentage','chosenDose','drugPercent','placeboPercent','differencePoints'])if($('#'+id))$('#'+id).oninput=e=>{v[id]=e.target.value;save();};
click('revealMed',()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.state;save();draw();feedback(validMedicineAnswer(t,v.state,v.answer)?'Prediction agrees. Record the evidence.':t.why,!validMedicineAnswer(t,v.state,v.answer));});
click('stepNetwork',()=>{if(!v.networkPrediction){feedback('Predict the final comparison first.',true);return;}v.steps=Math.min(5,v.steps+1);save();draw();});click('stepSelection',()=>{if(!v.selectionPrediction){feedback('Predict the final proportion first.',true);return;}v.step=Math.min(2,v.step+1);save();draw();});
click('placeEvidence',()=>{let i=v.evidenceIndex%4;if(v.evidenceClass!==(i===3?'clinical':'preclinical')){feedback(help,true);return;}if(!v.seen.includes(i))v.seen.push(i);v.evidenceIndex=(i+1)%4;v.evidenceClass='';save();feedback('Evidence source recorded.');remount();});click('revealDesign',()=>{v.designRevealed=true;save();draw();});click('inspectDose',()=>{if(!v.seen.includes(v.level))v.seen.push(v.level);save();draw();readEvidence();feedback('Observation recorded. Compare the benefit and harm.');});
$('#recordMed').onclick=()=>{if(record()===false)return;save();readEvidence();if(!valid()){feedback(help+(t.type==='compare'||t.type==='network'||t.type==='selection'?' Record the other comparisons too.':''),true);return;}if(!w.medPassed.includes(index))w.medPassed.push(index);if(w.medPassed.length===tasks.length){p.widgetDone=true;done();}save();$('#medProgress').textContent=w.medPassed.length+' / '+tasks.length+' complete';feedback('Evidence and reasoning recorded. '+help);};$('#nextMed').onclick=()=>{if(!w.medPassed.includes(index)){feedback('Complete every comparison in this challenge first.',true);return;}w.medTask=(index+1)%tasks.length;save();feedback('');remount();};draw();readEvidence();}
